contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test that: if the caller is authorized (wards[msg.sender]==1) then updatePrice(price) succeeds
    // and latestPrice equals price and lastPriceUpdate is updated to a nonzero timestamp; otherwise it reverts.
    // We cannot read wards directly, so we try calling updatePrice and observe success/revert and the public getters.
    function run(uint128 price) public payable {
        require(true);

        // Try to call updatePrice; record whether it reverted.
        bool reverted;
        try c.updatePrice(price) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read observed public state after attempt.
        uint128 observedPrice = c.latestPrice();
        uint256 observedLastUpdate = c.lastPriceUpdate();

        // If call succeeded (not reverted) then the contract must have latestPrice == price
        // and lastPriceUpdate must be nonzero (block.timestamp is nonzero in an active chain)
        // If call reverted then the state must not have been changed to the provided price at this caller's context.
        // We express a general property: either the call reverted, or both fields reflect the update.
        assert(reverted || (observedPrice == price && observedLastUpdate != 0));
    }

    receive() external payable { }
}

