contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that the checker will call with arbitrary inputs
    function run(uint256 assets, uint256 shares, address receiver, bool doMint) public payable {
        require(receiver != address(0), "nonzero receiver");
        // Ensure this contract is treated as the approved caller by using withApproval(receiver) since msg.sender must equal receiver for those functions.
        // The contract deploying c has become ward in C's constructor and is auth; however here InvMutTest is msg.sender for c calls.
        // The withApproval modifier requires msg.sender == owner (the 'receiver' param). To satisfy it, call functions by making receiver == address(this).
        // So we only proceed when receiver equals this contract to exercise the success branch; otherwise the call should revert due to withApproval.
        bool receiverIsThis = (receiver == address(this));

        // Read pre-call observable values that will be used in the assertion
        uint256 preTotalSupply = c.totalSupply();
        uint256 preTotalAssets = c.totalAssets();

        // We will attempt either deposit(assets, receiver) or mint(shares, receiver).
        bool reverted = false;
        uint256 returnedValue = 0;
        bytes memory emittedData; // not used directly, kept for clarity

        if (doMint) {
            // mint(shares, receiver) returns (uint256 assets)
            try c.mint(shares, receiver) returns (uint256 assetsOut) {
                returnedValue = assetsOut;
            } catch {
                reverted = true;
            }
        } else {
            // deposit(assets, receiver) returns (uint256 shares)
            try c.deposit(assets, receiver) returns (uint256 sharesOut) {
                returnedValue = sharesOut;
            } catch {
                reverted = true;
            }
        }

        // After the call, read observable values again
        uint256 postTotalSupply = c.totalSupply();
        uint256 postTotalAssets = c.totalAssets();

        // General rule asserted:
        // - If the call reverted, then it must be because withApproval failed (i.e., receiver != address(this)). We check that by asserting that if reverted then receiverIsThis == false.
        // - If the call did not revert, then receiver must have been address(this) (satisfying withApproval), and the emitted Deposit event must have matched the returnedValue:
        //   For deposit: returnedValue (shares) is <= postTotalSupply (since minting shares increases totalSupply) and postTotalAssets >= preTotalAssets (assets deposited increase managed assets) OR totalAssets may change as per investment manager but we at least ensure totalSupply changed non-decreasingly when deposit succeeded.
        //   For mint: returnedValue (assets) is <= postTotalAssets and postTotalSupply >= preTotalSupply.

        assert(
            reverted
            ? (!receiverIsThis)
            : (
                receiverIsThis
                && (
                    // when deposit succeeded, shares returned should not exceed new totalSupply and totalSupply is non-decreasing
                    (!doMint && returnedValue <= postTotalSupply && postTotalSupply >= preTotalSupply && postTotalAssets >= preTotalAssets)
                    // when mint succeeded, assets returned should not exceed new totalAssets and totalSupply is non-decreasing
                    || (doMint && returnedValue <= postTotalAssets && postTotalSupply >= preTotalSupply && postTotalAssets >= preTotalAssets)
                )
            )
        );
    }

    // allow receiving ether if tests decide to send it
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that the checker will call with arbitrary inputs
    function run(uint256 assets, uint256 shares, address owner, uint8 action) public payable {
        // action: 0=deposit,1=mint,2=withdraw,3=redeem,4=requestDeposit,5=requestRedeem,6=decreaseDepositRequest,7=decreaseRedeemRequest,8=collectDeposit,9=collectRedeem
        require(owner != address(0), "owner nonzero");
        require(action <= 9, "action range");

        // Read pre-call observable values
        uint256 preTotalSupply = c.totalSupply();
        uint256 preTotalAssets = c.totalAssets();

        // We will perform exactly one top-level call on c that may change state.
        bool reverted;
        // Each call is a top-level try, per constraints
        if (action == 0) {
            // deposit(assets, owner) requires msg.sender == owner via withApproval
            try c.deposit(assets, owner) returns (uint256) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else if (action == 1) {
            try c.mint(shares, owner) returns (uint256) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else if (action == 2) {
            try c.withdraw(assets, owner, owner) returns (uint256) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else if (action == 3) {
            try c.redeem(shares, owner, owner) returns (uint256) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else if (action == 4) {
            try c.requestDeposit(assets, owner) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else if (action == 5) {
            try c.requestRedeem(shares, owner) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else if (action == 6) {
            try c.decreaseDepositRequest(assets, owner) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else if (action == 7) {
            try c.decreaseRedeemRequest(shares, owner) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else if (action == 8) {
            try c.collectDeposit(owner) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.collectRedeem(owner) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Read post-call observable values
        uint256 postTotalSupply = c.totalSupply();
        uint256 postTotalAssets = c.totalAssets();

        // General rule asserted:
        // If the call reverted, then it must be because withApproval failed for calls that require it (actions 0..7 require withApproval(owner)), i.e., msg.sender != owner. In this test harness msg.sender is this contract, so reverted implies owner != address(this) for those actions. For collectDeposit/collectRedeem (8,9) there is no withApproval, so they should not revert due to withApproval; we allow revert for other reasons.
        // If the call did not revert, then it succeeded and as a basic safety property totalSupply and totalAssets must be non-decreasing (these operations should not reduce totalSupply/totalAssets observable by public getters).

        bool ownerIsThis = (owner == address(this));
        bool actionRequiresApproval = (action <= 7);

        assert(
            reverted
            ? (
                // If it required approval and reverted, then owner wasn't this contract (so withApproval failed)
                (actionRequiresApproval ? (!ownerIsThis) : true)
            )
            : (
                // If it did not revert, then totalSupply and totalAssets did not decrease
                (postTotalSupply >= preTotalSupply && postTotalAssets >= preTotalAssets)
            )
        );
    }

    // allow receiving ether if tests decide to send it
    receive() external payable {}
}

