contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // action: 0=deposit,1=mint,2=withdraw,3=redeem,4=requestDeposit,5=requestRedeem,6=decreaseDepositRequest,7=decreaseRedeemRequest,8=collectDeposit,9=collectRedeem,10=requestDepositWithPermit,11=requestRedeemWithPermit
    function run(uint256 assets, uint256 shares, address owner, uint8 action) public payable {
        require(owner != address(0), "owner nonzero");
        require(action <= 11, "action range");

        // Read pre-call observable values
        uint256 preTotalSupply = c.totalSupply();
        uint256 preTotalAssets = c.totalAssets();

        // We'll perform exactly one top-level mutating call. Use try/catch as a top-level statement for each possibility.
        bool reverted;
        uint256 returnedUint = 0;

        if (action == 0) {
            try c.deposit(assets, owner) returns (uint256 r) { reverted = false; returnedUint = r; } catch { reverted = true; }
        } else if (action == 1) {
            try c.mint(shares, owner) returns (uint256 r) { reverted = false; returnedUint = r; } catch { reverted = true; }
        } else if (action == 2) {
            try c.withdraw(assets, owner, owner) returns (uint256 r) { reverted = false; returnedUint = r; } catch { reverted = true; }
        } else if (action == 3) {
            try c.redeem(shares, owner, owner) returns (uint256 r) { reverted = false; returnedUint = r; } catch { reverted = true; }
        } else if (action == 4) {
            try c.requestDeposit(assets, owner) { reverted = false; } catch { reverted = true; }
        } else if (action == 5) {
            try c.requestRedeem(shares, owner) { reverted = false; } catch { reverted = true; }
        } else if (action == 6) {
            try c.decreaseDepositRequest(assets, owner) { reverted = false; } catch { reverted = true; }
        } else if (action == 7) {
            try c.decreaseRedeemRequest(shares, owner) { reverted = false; } catch { reverted = true; }
        } else if (action == 8) {
            try c.collectDeposit(owner) { reverted = false; } catch { reverted = true; }
        } else if (action == 9) {
            try c.collectRedeem(owner) { reverted = false; } catch { reverted = true; }
        } else if (action == 10) {
            // requestDepositWithPermit: needs ERC20 permit parameters; reuse shares/assets as deadline/v and r/s are zeroed
            uint256 deadline = assets; uint8 v = uint8(shares & 0xff);
            bytes32 r = bytes32(0); bytes32 s = bytes32(0);
            try c.requestDepositWithPermit(deadline, owner, deadline, v, r, s) { reverted = false; } catch { reverted = true; }
        } else {
            // action == 11: requestRedeemWithPermit
            uint256 deadline = assets; uint8 v = uint8(shares & 0xff);
            bytes32 r = bytes32(0); bytes32 s = bytes32(0);
            try c.requestRedeemWithPermit(deadline, owner, deadline, v, r, s) { reverted = false; } catch { reverted = true; }
        }

        // Read post-call observable values
        uint256 postTotalSupply = c.totalSupply();
        uint256 postTotalAssets = c.totalAssets();

        bool ownerIsThis = (owner == address(this));
        // actions that require withApproval: deposit(0), mint(1), withdraw(2), redeem(3), requestDeposit(4), requestRedeem(5), decreaseDepositRequest(6), decreaseRedeemRequest(7)
        bool actionRequiresApproval = (action <= 7);

        // General rule: if not reverted then totals did not decrease; if reverted and the action requires approval then owner != this.
        assert(
            reverted
            ? (actionRequiresApproval ? (!ownerIsThis) : true)
            : (postTotalSupply >= preTotalSupply && postTotalAssets >= preTotalAssets)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry performing the property test
    function run(uint128 price) public payable {
        require(true);

        // make this contract authorized (wards[msg.sender]=1) by using c.rely which requires auth;
        // the test contract was used to deploy c, so in constructor of C deployer got authority.
        // However the checker deploys a fresh C and passes it into this test's constructor, where
        // the deployer of C (externally) is the test deployer, not this contract. To ensure we have
        // auth, first try to call file which requires auth; if that reverts then we can't do rely.
        // Instead, we attempt to call c.rely(address(this)) and catch revert to record authorization outcome.

        bool reverted;
        try c.rely(address(this)) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read before-values
        uint128 beforePrice = c.latestPrice();
        uint256 beforeTs = c.lastPriceUpdate();

        bool callReverted;
        // attempt to call updatePrice; it should succeed iff we are authorized (i.e., rely didn't revert and thus granted us auth)
        try c.updatePrice(price) {
            callReverted = false;
        } catch {
            callReverted = true;
        }

        uint128 afterPrice = c.latestPrice();
        uint256 afterTs = c.lastPriceUpdate();

        // General rule:
        // If updatePrice did not revert then latestPrice equals the input price and lastPriceUpdate became nonzero
        // and is >= previous timestamp. If it reverted then state must be unchanged (price and timestamp stay equal to before-values).
        assert(
            (!callReverted && afterPrice == price && afterTs != 0 && afterTs >= beforeTs)
            || (callReverted && afterPrice == beforePrice && afterTs == beforeTs)
        );
    }

    receive() external payable {}
}

