    // single public entry: attempt to call updatePrice and observe whether it succeeds,
    // then assert the general relationship between inputs, observed success, and public getters.
    function run(uint128 price, address caller) public payable {
        require(caller != address(0), "caller-nonzero");

        // read before-values
        uint128 beforePrice = c.latestPrice();
        uint256 beforeTs = c.lastPriceUpdate();

        // We need to try to invoke updatePrice as if msg.sender == caller.
        // Since the InvMutTest contract is the msg.sender for calls from here, we must
        // use a low-level call to simulate a call that sets tx.origin/caller differently is impossible.
