        bool succeeded;
        // perform the call and catch revert without using try/catch (since updatePrice is external)
        // use low-level call encoding function selector and parameter
        bytes memory data = abi.encodeWithSelector(c.updatePrice.selector, price);
        (bool ok, bytes memory ret) = address(c).call(data);
        succeeded = ok;

        // read after-values (always allowed even if call reverted)
        uint128 afterPrice = c.latestPrice();
        uint256 afterTs = c.lastPriceUpdate();

        // The property:
        // - If the call succeeded, then latestPrice equals the provided price and lastPriceUpdate >= beforeTs.
        //   Also lastPriceUpdate should be nonzero (it is set to block.timestamp on success).
        // - If the call reverted, then latestPrice and lastPriceUpdate must be unchanged.
        assert(
            (succeeded && afterPrice == price && afterTs >= beforeTs && afterTs != 0)
            || (!succeeded && afterPrice == beforePrice && afterTs == beforeTs)
        );
    }

    receive() external payable {}
}

