contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single entry point for the property test
    function run(address caller, uint128 price) public payable {
        require(caller != address(0));
        // Ensure this contract is authorized first if caller should be authorized; we will test both cases.
        // Make this contract a ward so it can authorize others via rely.
        // As the deployer of c, the deployer ward was set in C constructor; here msg.sender is the test runner,
        // but the test contract is the deployer of c per harness, so it should already be a ward. Still, try to be explicit:
        // call rely(caller) if this contract is authorized
        bool canAuth;
        // Try to call rely to authorize 'caller'; detect revert to know whether this contract is authorized
        try c.rely(caller) {
            canAuth = true;
        } catch {
            canAuth = false;
        }

        // Read before values
        uint128 beforePrice = c.latestPrice();
        uint256 beforeTs = c.lastPriceUpdate();

        // Now attempt to have 'caller' invoke updatePrice(price).
        // We simulate the call from 'caller' by calling the target function on c via low-level call with msg.sender encoded as the caller
        // but since in this environment msg.sender for calls from this test is this contract, we cannot change msg.sender.
        // Instead, we check two cases: if we successfully authorized 'caller' above (canAuth == true), then calling updatePrice as this contract
        // AFTER setting wards[caller]==1 should allow this contract to call c.updatePrice (because rely was called and msg.sender==this contract)
        // But we need to test behavior for both authorized and unauthorized invocation origins. To do that we rely on the fact
        // that c.updatePrice is protected by auth modifier checking wards[msg.sender]==1. We can: (A) if canAuth==true, call c.updatePrice(price) here
        // which will succeed because this contract is a ward. (B) If canAuth==false, the call should revert for being unauthorized.

        bool reverted;
        if (canAuth) {
            // This contract is authorized and has already called rely(caller). Now calling updatePrice as this contract should succeed.
            try c.updatePrice(price) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // Not authorized: calling updatePrice must revert
            try c.updatePrice(price) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Read after values
        uint128 afterPrice = c.latestPrice();
        uint256 afterTs = c.lastPriceUpdate();

        // General rule asserted:
        // If the call did not revert, then latestPrice must equal the provided price and lastPriceUpdate must be >= beforeTs (timestamp non-decreasing)
        // If the call reverted, then both latestPrice and lastPriceUpdate must be unchanged.
        assert(
            (!reverted && afterPrice == price && afterTs >= beforeTs)
            || (reverted && afterPrice == beforePrice && afterTs == beforeTs)
        );
    }

    receive() external payable {}
}

