contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that will be called by the checker with arbitrary inputs
    function run(address caller, uint128 price) public payable {
        require(caller != address(0)); // avoid zero-address in authorization calls

        // Ensure this contract is authorized first by calling rely from constructor-sender: the test contract deployed c,
        // but wards[msg.sender] was set during C constructor to the deployer of C (the checker). We cannot rely on that,
        // so we attempt to toggle authorization via c.rely — that requires auth and thus must be executed by an authorized
        // party. We therefore query current wards(msg.sender) via the public getter: wards is in Auth as public, but there is
        // no direct getter declared for wards here; however Auth declared mapping public wards, so a getter exists.
        // We will read whether this contract is already authorized and branch behavior based on that.

        // read whether this test contract (msg.sender for subsequent calls) is authorized
        uint256 beforeWard = c.wards(address(this));

        // read current latestPrice and lastPriceUpdate
        uint128 beforePrice = c.latestPrice();
        uint256 beforeUpdateTime = c.lastPriceUpdate();

        bool reverted;
        // attempt to call updatePrice with provided price as this contract
        try c.updatePrice(price) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after values
        uint128 afterPrice = c.latestPrice();
        uint256 afterUpdateTime = c.lastPriceUpdate();

        // General rule asserted:
        // - If this contract was authorized (beforeWard == 1), the call must not revert, latestPrice must equal price,
        //   and lastPriceUpdate must be >= beforeUpdateTime and equal to block.timestamp (we cannot read block.timestamp from here,
        //   but we can at least require non-decrease and that when update occurred price changed to the input).
        // - If not authorized (beforeWard != 1), the call must revert and state must be unchanged.
        assert(
            (beforeWard == 1 && !reverted && afterPrice == price && afterUpdateTime >= beforeUpdateTime)
            ||
            (beforeWard != 1 && reverted && afterPrice == beforePrice && afterUpdateTime == beforeUpdateTime)
        );
    }

    // allow receiving ETH if needed (not used here)
    receive() external payable {}
 }

