    // single public test function: takes a candidate caller address (to become authorized or not)
    // and a price to set. The test will: ensure msg.sender (this contract) is authorized by calling rely,
    // then call updatePrice with provided price and assert the observable invariants.
    function run(uint128 price, address other) public payable {
        require(price != 0 || price == 0, true);
        // authorise this contract (InvMutTest) by calling rely via the deployer of c which initially set wards[msg.sender]=1 in constructor.
        // The InvMutTest is the msg.sender for calls into c, but only the address that deployed c was authorized.
        // However the test has access only to c's public API. The deployer of c is outside our control in the checker,
        // so instead we exercise both behaviors: try updatePrice and observe whether it reverted, and if it succeeded then
        // latestPrice must equal 'price' and lastPriceUpdate must equal block.timestamp at time of call.

        bool reverted;
        // attempt call
        try c.updatePrice(price) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read public getters
        uint128 observedPrice = c.latestPrice();
        uint256 observedLast = c.lastPriceUpdate();

        // If the call did not revert, then latestPrice must equal the price we passed,
        // and lastPriceUpdate must be equal to the current block.timestamp (the time of the call).
        // If it reverted, then neither latestPrice nor lastPriceUpdate should have been changed to the new price/timestamp simultaneously.
        // We express a general invariant: either the call reverted, or the observedPrice equals price and observedLast == block.timestamp.
        // Note: block.timestamp is readable in this context and matches the time of the call above.
        assert(reverted || (observedPrice == price && observedLast == block.timestamp));
    }

    receive() external payable {}
}

